{
    "items": [
        {
            "chunk_id": "9fdd77bb1472",
            "decision": "keep",
            "confidence": 0.9,
            "knowledge_value": "high",
            "reason": "段落描述了AI视频产业相关的标准化政策，包括标准制定目标、企业参与和国际标准制定，这些是可沉淀的产业知识，不包含具体事件或噪声。",
            "knowledge_spans": [
                {
                    "text": "工业和信息化部等四部门印发《国家人工智能产业综合标准化体系建设指南（2024版）》。到2026年，标准与产业科技创新的联动水平持续提升，新制定国家标准和行业标准50项以上，引领人工智能产业高质量发展的标准体系加快形成。开展标准宣贯和实施推广的企业超过1000家，标准服务企业创新发展的成效更加凸显。参与制定国际标准20项以上，促进人工智能产业全球化发展",
                    "role": "AI视频产业标准化政策",
                    "stability": "high"
                }
            ],
            "event_residue": "",
            "drop_target": ""
        },
        {
            "chunk_id": "db4bb6ece107",
            "decision": "split",
            "confidence": 0.8,
            "knowledge_value": "medium",
            "reason": "段落包含Sora模型的技术特性（如视频时长、质量对比）和行业影响，这些是可沉淀的知识；同时包含周鸿祎发布微博的具体事件，需要分离。",
            "knowledge_spans": [
                {
                    "text": "Sora模型可以生成长达1分钟的高清视频，几乎可以秒杀世界上任何一个视频生成平台（Pika只能生成3-15秒的视频，而且一眼就看出来是AI制造的，根本没法使用），虽然目前还没正式公开使用，但消息已公布，已经引发了全球热议，Sora的出现将可能重新定义现有短视频行业的格局。",
                    "role": "Sora模型技术优势与行业影响",
                    "stability": "medium"
                }
            ],
            "event_residue": "2月16日，360创始人周鸿祎发布微博提到自己对Sora的看法，周鸿祎认为，Sora的诞生意味着AGI（通用人工智能）实现可能从10年缩短至一两年。",
            "drop_target": "event"
        },
        {
            "chunk_id": "92b1df7b23b4",
            "decision": "split",
            "confidence": 0.85,
            "knowledge_value": "high",
            "reason": "段落包含Pika Labs的团队背景、技术功能（如生成和编辑能力、语义理解）和产品特性，这些是可沉淀的知识；同时包含创始人的个人背景和公司关系等事件性信息，需要分离。",
            "knowledge_spans": [
                {
                    "text": "Pika1.0能够生成和编辑3D动画、动漫、卡通和电影。几乎不需要任何门槛，用户只需要输入一句话，就可以生成想要的各种风格的视频。此外，用户还能够通过Pika实现画布延展、局部修改、视频时长拓展等编辑需求。在宣传片中，Pika1.0拥有强大的语义理解能力，输入“马斯克穿着太空服，3D动画”的关键词，一个身穿太空服的卡通马斯克便出现了，身后还有SpaceX的火箭。文生视频的清晰度和连贯性，远超市面上其他AI视频生成产品。",
                    "role": "Pika1.0技术功能与性能",
                    "stability": "high"
                }
            ],
            "event_residue": "Pika Labs的创始团队目前只有4个人。联合创始人郭文景，是来自杭州的一位“95后”女孩，曾被誉为“天才少女”。郭文景与另一位联合创始人孟晨琳同为斯坦福AI Lab的华人女博士，今年4月，二人一起从斯坦福退学创业。郭文景的父亲，是A股上市公司信雅达实控人郭华强。信雅达发布公告，承认郭文景与郭华强的父女关系，但“除上述关系外，公司与Pika无其他关系。截至目前，郭文景未在公司担任任何职务，公司未投资Pika，也未与Pika有任何业务往来。”",
            "drop_target": "event"
        },
        {
            "chunk_id": "41fe4cc4ab0d",
            "decision": "split",
            "confidence": 0.75,
            "knowledge_value": "medium",
            "reason": "段落包含Pika的功能演进（如支持图片转视频等）和合作信息，这些是可沉淀的知识；同时包含《流浪地球3》发布会等具体事件，需要分离。",
            "knowledge_spans": [
                {
                    "text": "最初，Pika只支持文生视频，后来逐渐支持图片转视频、相机控制、文字和Logo嵌入视频中等。Pika1.0宣传片中的许多功能，目前Discord上的版本并不支持，只能等网页版开放测评后验证。",
                    "role": "Pika功能演进与版本限制",
                    "stability": "medium"
                }
            ],
            "event_residue": "Pika也并非第一次在众人前亮相。今年11月初，《流浪地球3》的发布会上，电影工业化实验室G!Lab官宣成立。郭帆导演介绍了一批战略合作的科技公司，包括商汤科技、小米、华为等，还有Pika Labs。",
            "drop_target": "event"
        }
    ]
}
